<template>
  <PasswordRecovery v-if="route.name==='recovery'"/><div v-else-if="isAuth" class="auth-shell"><section class="auth-card"><div class="auth-brand"><span>✚</span> 东软体检 <small>HEALTHCARE</small></div><p class="eyebrow">{{ route.name==='login'?'WELCOME BACK':'GET STARTED' }}</p><h1>{{ route.name==='login'?'欢迎回来':'创建健康账户' }}</h1><p class="muted">{{ route.name==='login'?'登录后开始您的体检预约':'填写基本信息，开启您的体检之旅' }}</p>
    <form v-if="route.name==='login'" @submit.prevent="login" class="form"><label>手机号码<input v-model.trim="loginForm.userId" inputmode="numeric" maxlength="11" required placeholder="请输入手机号码"></label><label>密码<input v-model="loginForm.password" type="password" required placeholder="请输入密码"></label><button class="primary wide" :disabled="busy">{{busy?'登录中…':'登 录'}}</button><p class="auth-switch"><router-link to="/recovery">忘记密码？</router-link></p><p class="auth-switch">还没有账户？ <router-link to="/register">立即注册</router-link></p></form>
    <form v-else @submit.prevent="register" class="form register-form"><label>手机号码<input v-model.trim="registration.userId" inputmode="numeric" maxlength="11" required placeholder="11 位手机号码"></label><label>真实姓名<input v-model.trim="registration.realName" maxlength="20" required placeholder="请输入姓名"></label><label>身份证号<input v-model.trim="registration.identityCard" maxlength="18" required placeholder="请输入身份证号"></label><div class="form-row"><label>出生日期<input v-model="registration.birthday" type="date" required></label><label>性别<select v-model.number="registration.sex"><option :value="1">男</option><option :value="0">女</option></select></label></div><label>密码<input v-model="registration.password" type="password" maxlength="20" required placeholder="最多 20 位"></label><label>确认密码<input v-model="confirmPassword" type="password" maxlength="20" required placeholder="再次输入密码"></label><button class="primary wide" :disabled="busy">{{busy?'提交中…':'完成注册'}}</button><p class="auth-switch">已有账户？ <router-link to="/login">返回登录</router-link></p></form>
    <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p></section></div>
  <div v-else class="layout" :class="'page-'+route.name"><header class="header"><div class="header-inner"><router-link class="logo" to="/home"><span>✚</span><div>东软体检<small>NEUSOFT HEALTH</small></div></router-link><nav class="desktop-nav"><router-link to="/home">首页</router-link><router-link to="/appointment">体检预约</router-link><router-link to="/appointmentList">我的预约</router-link><router-link to="/reportList">体检报告</router-link></nav><router-link class="profile-link" to="/personal"><span class="avatar">{{initial}}</span><span>{{ user?.realName || '个人中心' }}</span></router-link></div></header>
    <main class="container"><div v-if="error" class="error banner" role="alert">{{error}} <button @click="error=''">×</button></div><div v-if="notice" class="notice" role="status">{{notice}}</div>
      <template v-if="route.name==='home'"><section class="home-banner"><img src="/img/logo.png" alt="健康生活"></section><div class="home-services"><button @click="go('/consultation')"><img src="/img/menu01.png" alt=""><span><strong>免费咨询</strong><small>专业医师为您解答</small></span></button><button @click="go('/consultation')"><img src="/img/menu02.png" alt=""><span><strong>网络问诊</strong><small>提交问题查看回复</small></span></button><button @click="go('/doctors')"><img src="/img/menu03.png" alt=""><span><strong>e 门诊</strong><small>查看医生与预约</small></span></button><button @click="router.push({name:'services',query:{tab:'chronic'}})"><img src="/img/menu04.png" alt=""><span><strong>慢病管理</strong><small>记录日常健康数据</small></span></button><button @click="router.push({name:'services',query:{tab:'care'}})"><img src="/img/menu05.png" alt=""><span><strong>上门护理</strong><small>提交服务需求</small></span></button><button @click="router.push({name:'services',query:{tab:'group'}})"><img src="/img/menu06.png" alt=""><span><strong>团检预约</strong><small>提交团体体检需求</small></span></button></div><div class="section-head"><h2>我的健康报告</h2></div><div class="home-report"><span>随时随地查看体检报告</span><button class="primary" @click="go('/reportList')">立即查看</button></div><div class="section-head"><h2>推荐医生</h2><button class="section-link" @click="go('/doctors')">更多 →</button></div><div class="doctor-profiles"><button v-for="d in doctors" :key="d.id" class="doctor-profile-card" @click="openDoctor(d)"><img class="doctor-photo" :src="d.photo" :alt="d.name + '照片'"><span class="doctor-copy"><strong>{{d.name}}</strong><small>{{d.title}}</small></span></button></div><div class="section-head"><h2>健康评估</h2><button class="section-link" @click="go('/assessments')">更多 →</button></div><div class="home-assess"><button v-for="n in 3" :key="n" @click="go('/assessments')"><img :src="'/img/assess'+n+'.png'" alt="健康评估"></button></div><div class="section-head"><h2>健康资讯</h2><button class="section-link" @click="go('/healthNews')">更多 →</button></div><div class="info-gallery" @click="go('/healthNews')"><article><img src="/img/info1.png" alt=""><div><strong>关注身体健康</strong><p>通过定期体检了解身体状况。</p></div></article><article><img src="/img/info2.png" alt=""><div><strong>养成健康习惯</strong><p>关爱自己，从日常开始。</p></div></article></div></template>
      <template v-else-if="route.name==='appointment'"><div class="page-intro"><p class="eyebrow">WHO IS THIS FOR?</p><h1>为谁预约体检？</h1><p>请选择体检人，再选择机构、套餐和日期。</p></div><div class="appointment-banner"><img src="/img/yuyue.png" alt="体检预约"></div><div class="person-grid"><button class="person-choice" @click="chooseSelf"><img class="person-illustration" src="/img/benrenyuyue.png" alt=""><strong>本人预约</strong><small>{{user?.realName}} · 使用当前账户信息</small><b>选择本人 →</b></button><button class="person-choice" :class="{selected:showFamily}" @click="showFamily=!showFamily"><img class="person-illustration" src="/img/jiashuyuyue.png" alt=""><strong>家属预约</strong><small>填写家属信息，由您管理预约和报告</small><b>{{showFamily?'收起信息 ↑':'填写信息 →'}}</b></button></div><form v-if="showFamily" class="family-card form" @submit.prevent="chooseFamily"><h3>家属体检人信息</h3><p class="muted">信息用于本次预约，提交前请确认已获得家属同意。</p><label>姓名<input v-model.trim="familyForm.patientName" maxlength="20" required placeholder="请输入家属姓名"></label><label>身份证号<input v-model.trim="familyForm.patientIdentityCard" maxlength="18" minlength="18" required placeholder="请输入 18 位身份证号"></label><div class="form-row"><label>出生日期<input v-model="familyForm.patientBirthday" type="date" :max="todayString" required></label><label>性别<select v-model.number="familyForm.patientSex"><option :value="1">男</option><option :value="0">女</option></select></label></div><button class="primary">下一步 · 选择机构 →</button></form><p class="family-note">同一体检人有未归档预约时不能重复预约；您可以继续为其他家人预约。</p></template>
      <template v-else-if="route.name==='hospital'"><div class="page-intro"><p class="eyebrow">STEP 01 / 03</p><h1>选择体检机构</h1><p>选择适合您的体检地点，开启预约。</p></div><div class="steps"><span class="current">01 选择机构</span><span>02 选择套餐</span><span>03 选择日期</span></div><div v-if="loading" class="empty">正在加载体检机构…</div><div v-else-if="!hospitals.length" class="empty">暂无可预约的体检机构</div><div v-else class="hospital-grid"><article v-for="h in hospitals" :key="h.hpId" class="hospital-card"><img :src="imagePath(h.picture)" alt="医院图片" @error="fallbackImage"><div class="hospital-body"><span class="pill">开放预约</span><h3>{{h.name}}</h3><p><i class="fa fa-map-marker"></i> {{h.address}}</p><p><i class="fa fa-clock-o"></i> {{h.businessHours}}</p><p><i class="fa fa-phone"></i> {{h.telephone}}</p><button class="outline" @click="selectHospital(h)">选择机构 →</button></div></article></div></template>
      <template v-else-if="route.name==='setmeal'"><div class="page-intro"><button class="back" @click="go('/hospital')">← 返回选择机构</button><p class="eyebrow">STEP 02 / 03</p><h1>选择体检套餐</h1><p>已选机构：{{selection.hospital?.name || '未选择'}}</p></div><div class="steps"><span>✓ 选择机构</span><span class="current">02 选择套餐</span><span>03 选择日期</span></div><div class="tabs"><button :class="{active:mealType===1}" @click="setType(1)">男士套餐</button><button :class="{active:mealType===0}" @click="setType(0)">女士套餐</button></div><div v-if="loading" class="empty">正在加载套餐…</div><div v-else-if="!meals.length" class="empty">当前分类暂无套餐</div><div v-else class="meal-grid"><article v-for="m in meals" :key="m.smId" class="meal-card"><span class="pill soft">{{m.type===1?'男士体检':'女士体检'}}</span><h3>{{m.name}}</h3><p>关爱身体，从定期体检开始。</p><button type="button" class="meal-toggle" :aria-expanded="expandedMeal===m.smId" @click="toggleMealDetails(m)">{{expandedMeal===m.smId ? '收起检查项目 ↑' : '查看检查项目 ↓'}}</button><div v-if="expandedMeal===m.smId" class="meal-details"><p v-if="detailLoading">正在加载检查项目…</p><p v-else-if="!mealDetails[m.smId]">检查项目加载失败，请收起后重试。</p><p v-else-if="!mealDetails[m.smId].length">此套餐暂无检查项目。</p><div v-for="item in (mealDetails[m.smId] || [])" :key="item.ciId" class="meal-item"><strong>{{item.ciName}}</strong><p>{{item.ciContent}}</p><small v-if="item.meaning">{{item.meaning}}</small><div v-if="item.details.length" class="detail-tags"><span v-for="detail in item.details" :key="detail.cdId">{{detail.name}}</span></div></div></div><div class="meal-foot"><strong><small>¥</small>{{m.price}}</strong><button class="primary" @click="selectMeal(m)">选择套餐 →</button></div></article></div></template>
      <template v-else-if="route.name==='selectDate'"><div class="page-intro"><button class="back" @click="go('/setmeal')">← 返回选择套餐</button><p class="eyebrow">STEP 03 / 03</p><h1>选择体检日期</h1><p>{{selection.hospital?.name}} · {{selection.meal?.name}}</p></div><div class="steps"><span>✓ 选择机构</span><span>✓ 选择套餐</span><span class="current">03 选择日期</span></div><div class="calendar-card"><div class="calendar-head"><button @click="shiftMonth(-1)" aria-label="上个月">‹</button><strong>{{calendarYear}} 年 {{calendarMonth}} 月</strong><button @click="shiftMonth(1)" aria-label="下个月">›</button></div><div class="calendar-grid week"><span v-for="d in ['一','二','三','四','五','六','日']" :key="d">{{d}}</span></div><div v-if="loading" class="empty">正在加载日历…</div><div v-else class="calendar-grid"><span v-for="n in leadingDays" :key="'blank'+n"></span><button v-for="day in calendar" :key="day.date" :disabled="!day.available" :class="{chosen:selection.date===day.date}" @click="pickDate(day.date)"><span>{{Number(day.date.slice(-2))}}</span><small v-if="day.available">余 {{day.remaining}}</small><small v-else-if="day.capacity>0 && day.remaining===0">已满</small></button></div><p class="calendar-note">开放日期和每日名额由体检机构设置；提交预约时将再次检查。</p><button class="primary wide" :disabled="!selection.date" @click="go('/confirmOrder')">下一步 · 确认预约</button></div></template>
      <template v-else-if="route.name==='confirmOrder'"><div class="page-intro"><button class="back" @click="go('/selectDate')">← 返回选择日期</button><p class="eyebrow">REVIEW YOUR APPOINTMENT</p><h1>确认你的订单</h1><p>请核对体检人和预约信息。</p></div><div class="confirm-card"><div class="card-title">体检人信息</div><div class="info-row"><span>体检人</span><strong>{{selection.patient?.patientName || user?.realName}}（{{selection.patient?.patientType===2?'家属':'本人'}}）</strong></div><div class="info-row"><span>性别</span><strong>{{(selection.patient?.patientSex ?? user?.sex)===0?'女':'男'}}</strong></div><div class="info-row"><span>出生日期</span><strong>{{selection.patient?.patientType===2 ? selection.patient?.patientBirthday : user?.birthday}}</strong></div><div class="info-row"><span>身份证号</span><strong>{{maskId(selection.patient?.patientType===2 ? selection.patient?.patientIdentityCard : user?.identityCard)}}</strong></div><div class="info-row"><span>预约账号</span><strong>{{user?.userId}}</strong></div><div class="card-title">预约详情</div><div class="info-row"><span>体检机构</span><strong>{{selection.hospital?.name}}</strong></div><div class="info-row"><span>机构地址</span><strong>{{selection.hospital?.address}}</strong></div><div class="info-row"><span>营业时间</span><strong>{{selection.hospital?.businessHours}}</strong></div><div class="info-row"><span>机构电话</span><strong>{{selection.hospital?.telephone}}</strong></div><div class="info-row"><span>体检套餐</span><strong>{{selection.meal?.name}}</strong></div><div class="info-row"><span>体检日期</span><strong>{{selection.date}}</strong></div><p class="muted pay-note">使用模拟支付，不产生实际扣款。</p></div><div class="payment-bar"><span>实付款：<strong>¥ {{selection.meal?.price}}</strong></span><button :disabled="busy || !selection.date" @click="submitOrder">{{busy?'处理中…':'确认支付'}}</button></div></template>
      <template v-else-if="route.name==='appointmentSuccess'"><div class="success-page"><div class="success-heading">预约成功</div><div class="success-band"></div><div class="success-check">✓</div><h1>恭喜您预约成功！</h1><p>模拟支付已完成，请按预约日期前往体检机构。</p><p v-if="route.query.orderId">预约编号 #{{route.query.orderId}}</p><button class="success-order" @click="go('/appointmentList')">查看订单</button><button class="primary success-family" @click="go('/appointment')">继续为家人预约</button></div></template>
      <template v-else-if="route.name==='appointmentList' || route.name==='reportList'"><div class="page-intro"><button class="back" @click="backFromList">← 返回{{route.query.from==='personal'?'个人中心':'首页'}}</button><p class="eyebrow">{{route.name==='reportList'?'YOUR HEALTH RECORDS':'YOUR APPOINTMENTS'}}</p><h1>{{route.name==='reportList'?'体检报告':'我的预约'}}</h1><p>{{route.name==='reportList'?'查看已归档的体检报告。':'查看并管理您的体检预约。'}}</p></div><div v-if="route.name==='reportList'" class="report-consult-banner" @click="go('/consultation')"><img src="/img/report.png" alt="免费解读体检报告，点击咨询"></div><div v-if="route.name==='appointmentList'" class="tabs"><button :class="{active:orderState===1}" @click="changeOrderState(1)">未归档</button><button :class="{active:orderState===2}" @click="changeOrderState(2)">已归档</button><button :class="{active:orderState===3}" @click="changeOrderState(3)">已取消</button></div><div v-if="loading" class="empty">正在加载…</div><div v-else-if="!orders.length" class="empty"><i class="fa fa-calendar-o"></i><p>暂无{{route.name==='reportList'?'体检报告':'预约记录'}}</p><button class="outline" @click="go('/appointment')">去预约体检</button></div><div v-else-if="route.name==='reportList'" class="report-list"><button v-for="o in orders" :key="o.orderId" class="report-list-row" @click="openReport(o)"><i class="fa fa-file-text-o"></i><span><strong>{{formatReportDate(o.orderDate)}} 体检报告</strong><small>{{o.hospitalName || '体检机构'}} · {{o.patientName || user?.realName}}</small></span><b>›</b></button></div><div v-else class="order-list"><article v-for="o in orders" :key="o.orderId" class="order-card"><div class="order-top"><span>预约编号 #{{o.orderId}}</span><span class="pill" :class="{soft:o.state===2}">{{o.state===1?'未归档':o.state===2?'已归档':'已取消'}}</span></div><div class="order-content"><div><h3>{{o.mealName || '体检套餐'}}</h3><p>体检人：{{o.patientName || user?.realName}}（{{o.patientType===2?'家属':'本人'}}）</p><p>{{o.hospitalName || '体检机构'}} · {{o.orderDate}}</p><p>支付状态：{{o.paymentStatus==='UNPAID'?'待支付':o.paymentStatus==='PAID'?'已支付':o.paymentStatus==='REFUNDED'?'已模拟退款':'已取消'}} · ¥ {{o.paymentAmount ?? '—'}}</p></div><button v-if="o.state===1 && o.paymentStatus==='UNPAID'" class="primary" :disabled="busy" @click="payOrder(o)">模拟支付 →</button><button v-if="o.state===2" class="outline" @click="openReport(o)">查看报告 →</button><button v-else-if="o.state===1" class="text-danger" @click="cancelOrder(o)">取消预约</button></div></article></div></template>
      <template v-else-if="route.name==='report'"><div class="page-intro"><button class="back" @click="router.push({name:'reportList',query:route.query.from==='personal'?{from:'personal'}:{}})">← 返回报告列表</button><p class="eyebrow">EXAMINATION REPORT</p><h1>{{formatReportDate(reportOrder?.orderDate)}}体检报告</h1><p>预约编号 #{{reportOrderId}} · 体检人：{{reportOrder?.patientName || user?.realName}} · 检查结果与总检结论</p></div><div v-if="loading" class="empty">正在加载报告…</div><template v-else><div class="report-tabs"><button :class="{active:reportTab==='summary'}" @click="reportTab='summary'">总检结论</button><button :class="{active:reportTab==='details'}" @click="reportTab='details'">报告详情</button></div><section v-if="reportOrder && reportTab==='summary'" class="report-panel consultation-panel"><h2>免费在线咨询</h2><p class="muted" style="margin:14px 0">对报告有疑问？提交问题并查看回复。</p><button class="primary" @click="router.push({name:'consultation',query:{orderId:reportOrderId}})">咨询报告 →</button></section><section v-if="reportTab==='summary'" class="report-panel"><h2>异常项</h2><div v-if="!abnormalItems.length" class="muted report-empty">暂无标记为异常的检查项</div><div v-for="d in abnormalItems" :key="d.cidrId" class="result-row"><div><strong>{{d.name}}</strong><small>{{d.itemName}}{{d.normalValueString ? ' · 参考范围：'+d.normalValueString : ''}} {{d.unit || ''}}</small></div><span class="abnormal">{{d.value || '未填写'}} · 异常</span></div></section><section v-if="reportTab==='summary'" class="report-panel"><h2>尊敬的顾客，您本次体检结论如下：</h2><div v-if="!conclusions.length" class="muted report-empty">暂无总检结论</div><div v-for="(o,i) in conclusions" :key="o.orId" class="summary-title">{{i+1}}、{{o.title}}</div></section><section v-if="reportTab==='summary' && conclusions.length" class="report-panel"><h2>尊敬的顾客，您本次体检建议如下：</h2><div v-for="(o,i) in conclusions" :key="o.orId" class="result"><h3>{{i+1}}、{{o.title}}</h3><p>{{o.content || '暂无内容'}}</p></div></section><section v-if="reportTab==='details'" class="report-panel report-details"><div v-if="!reports.length" class="muted report-empty">暂无检查结果</div><article v-for="r in reports" :key="r.cirId" class="report-item"><h3>{{r.ciName}}</h3><div v-if="!r.details.length" class="muted">暂无明细</div><div v-for="d in r.details" :key="d.cidrId" class="result-row"><div><strong>{{d.name}}</strong><small>{{d.normalValueString ? '参考范围：'+d.normalValueString : ''}} {{d.unit || ''}}</small></div><span :class="{abnormal:d.isError===1}">{{d.value || '未填写'}} {{d.unit || ''}}<small v-if="d.normalValueString">正常值范围：{{d.normalValueString}}</small></span></div></article></section></template></template>
      <ServiceHub v-else-if="route.name==='services'"/><DoctorAppointments v-else-if="route.name==='doctorAppointments'"/><Consultation v-else-if="route.name==='consultation'"/><HealthTools v-else-if="route.name==='assessments'"/><HealthNews v-else-if="route.name==='healthNews'"/><template v-else-if="route.name==='doctors'"><div class="page-intro"><button class="back" @click="go('/home')">← 返回首页</button><p class="eyebrow">HEALTH TEAM</p><h1>医生介绍</h1><p>了解体检团队的服务方向。</p></div><div class="doctors-page"><button v-for="d in doctors" :key="d.id" class="doctor-profile-card" @click="openDoctor(d)"><img class="doctor-photo" :src="d.photo" :alt="d.name + '照片'"><span class="doctor-copy"><strong>{{d.name}}</strong><small>{{d.department}} · {{d.title}}</small><em>{{d.summary}}</em></span><b>查看介绍 →</b></button></div></template>
      <template v-else-if="route.name==='doctor'"><div class="page-intro"><button class="back" @click="go('/doctors')">← 返回医生列表</button><p class="eyebrow">DOCTOR PROFILE</p><h1>医生介绍</h1></div><article v-if="selectedDoctor" class="doctor-detail"><div class="doctor-detail-head"><img class="doctor-photo large" :src="selectedDoctor.photo" :alt="selectedDoctor.name + '照片'"><div><h2>{{selectedDoctor.name}}</h2><p>{{selectedDoctor.department}} · {{selectedDoctor.title}}</p></div></div><section><h3>医生简介</h3><p>{{selectedDoctor.introduction}}</p></section><section><h3>服务方向</h3><div class="specialty-tags"><span v-for="item in selectedDoctor.specialties" :key="item">{{item}}</span></div></section><section><h3>预约须知</h3><p>请选择日期提交预约，系统将生成当日排队号；实际出诊安排以机构确认为准。</p></section><button class="primary" @click="router.push({name:'doctorAppointments',query:{id:selectedDoctor.id}})">预约医生并排号 →</button> <button class="outline" @click="go('/doctors')">查看其他医生</button></article><div v-else class="empty">未找到相关医生 <button class="back" @click="go('/doctors')">返回医生列表</button></div></template>
      <template v-else-if="route.name==='personal'"><div class="page-intro"><p class="eyebrow">MY ACCOUNT</p><h1>个人中心</h1><p>管理您的个人信息和体检记录。</p></div><div class="personal-card"><div class="personal-user"><img class="avatar large" src="/img/user.png" alt=""><div><h2>{{user?.realName}}</h2><p>{{user?.userId}}</p></div></div><div class="personal-links"><button @click="router.push({name:'appointmentList',query:{from:'personal'}})">我的预约 <span>→</span></button><button @click="router.push({name:'reportList',query:{from:'personal'}})">体检报告 <span>→</span></button><button @click="router.push({name:'consultation',query:{from:'personal'}})">我的咨询 <span>→</span></button><button @click="router.push({name:'doctorAppointments',query:{from:'personal'}})">医生预约 <span>→</span></button><button @click="router.push({name:'services',query:{from:'personal'}})">我的服务 <span>→</span></button><button @click="router.push({name:'services',query:{tab:'shop',from:'personal'}})">商城订单 <span>→</span></button><button @click="logout">退出登录 <span>→</span></button></div></div></template>
    </main><footer class="footer">东软体检 · 让健康更简单</footer><nav class="mobile-nav"><router-link to="/home"><i class="fa fa-home"></i>首页</router-link><router-link to="/appointment"><i class="fa fa-calendar-plus-o"></i>预约</router-link><router-link to="/reportList"><i class="fa fa-file-text-o"></i>报告</router-link><router-link to="/personal"><i class="fa fa-user-o"></i>我的</router-link></nav>
  </div>
</template>
<script setup>
import { ref, reactive, computed, watch, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import axios from 'axios'
const doctors=ref([])
import PasswordRecovery from './components/PasswordRecovery.vue'
import ServiceHub from './components/ServiceHub.vue'
import Consultation from './components/Consultation.vue'
import DoctorAppointments from './components/DoctorAppointments.vue'
import HealthTools from './components/HealthTools.vue'
import HealthNews from './components/HealthNews.vue'
const route=useRoute(), router=useRouter(), api=axios.create({baseURL:'/tijian',timeout:10000})
const read=(key,fallback=null)=>{try{return JSON.parse(sessionStorage.getItem(key))||fallback}catch{return fallback}}
const user=ref(read('tijianUser')), selection=reactive(read('tijianSelection',{})), error=ref(''),notice=ref(''),busy=ref(false),loading=ref(false)
const showFamily=ref(false), familyForm=reactive({patientName:'',patientSex:1,patientIdentityCard:'',patientBirthday:''}), todayString=new Date().toLocaleDateString('en-CA')
const loginForm=reactive({userId:'',password:''}), registration=reactive({userId:'',password:'',realName:'',sex:1,identityCard:'',birthday:'',userType:1}),confirmPassword=ref('')
const reportTab=ref('summary')
const hospitals=ref([]),meals=ref([]),mealType=ref(1),mealDetails=reactive({}),expandedMeal=ref(null),detailLoading=ref(false),calendar=ref([]),orderState=ref(1),orders=ref([]),reportOrder=ref(null),reports=ref([]),conclusions=ref([])
const today=new Date(), calendarYear=ref(today.getFullYear()),calendarMonth=ref(today.getMonth()+1)
const abnormalItems=computed(()=>reports.value.flatMap(r=>(r.details || []).filter(d=>d.isError===1).map(d=>({...d,itemName:r.ciName}))))
const selectedDoctor=computed(()=>doctors.value.find(d=>d.id===route.query.id || d.legacyIds?.includes(route.query.id)))
const isAuth=computed(()=>['login','register','recovery'].includes(route.name)),initial=computed(()=>user.value?.realName?.slice(0,1)||'我'),reportOrderId=computed(()=>Number(route.query.orderId)),leadingDays=computed(()=>calendar.value.length?calendar.value[0].dayOfWeek-1:0)
api.interceptors.response.use(response=>response, err=>{
  if(err.response?.status===401 && !['login','register','recovery'].includes(route.name)) {
    sessionStorage.removeItem('tijianUser'); user.value=null; router.replace('/login');
  }
  return Promise.reject(err)
})
const call=async(path,data)=>(await api.post(path,data)).data
onMounted(async()=>{
  if(!user.value) return
  try { const session=await api.get('/auth/session'); if(session.data.userId!==user.value.userId) throw new Error('session mismatch'); const profile=await api.get('/users/me'); if(!profile.data || profile.data.userId!==session.data.userId) throw new Error('profile mismatch'); user.value=profile.data; sessionStorage.setItem('tijianUser',JSON.stringify(profile.data)); await loadDoctors() }
  catch(e) { sessionStorage.removeItem('tijianUser'); user.value=null; await router.replace('/login') }
})
function fail(e){error.value=e.response?.status===409?'操作冲突：该体检人可能已有未归档预约，或所选日期名额已满。':e.response?.status===400?'信息不完整或格式不正确，请检查后重试。':'操作未完成，请检查服务是否启动后重试。';notice.value=''}
function success(s){error.value='';notice.value=s;setTimeout(()=>{notice.value=''},3500)}
async function loadDoctors(){const list=await call('/doctorAppointments/doctors',{});doctors.value=list.map(d=>({...d,photo:'/img/user.png',department:'健康体检',title:'体检医生',summary:d.serviceArea || '体检服务与健康咨询',introduction:d.introduction || '提供体检项目、报告及预约相关沟通服务。',specialties:d.specialties ? d.specialties.split(',') : ['体检咨询','报告沟通']}))}
function openDoctor(doctor){error.value='';router.push({name:'doctor',query:{id:doctor.id}})}
function maskId(value){return value && value.length>=8 ? value.slice(0,4)+'**********'+value.slice(-4) : '未填写'}
function go(path){error.value='';router.push(path)} function saveSelection(){sessionStorage.setItem('tijianSelection',JSON.stringify(selection))}
async function login(){busy.value=true;error.value='';try{const d=await call('/users/getUsersByUserIdByPass',loginForm);if(!d){error.value='手机号或密码不正确';return}user.value=d;sessionStorage.setItem('tijianUser',JSON.stringify(d));loginForm.password='';await loadDoctors();go('/home')}catch(e){fail(e)}finally{busy.value=false}}
async function register(){if(registration.password!==confirmPassword.value){error.value='两次输入的密码不一致';return}busy.value=true;error.value='';try{await call('/users/saveUsers',registration);loginForm.userId=registration.userId;registration.password='';confirmPassword.value='';await router.push('/login');success('注册成功，请登录')}catch(e){if(e.response?.status===409)error.value='该手机号已注册';else fail(e)}finally{busy.value=false}}
async function logout(){try{await call('/auth/logout',{})}catch(e){if(e.response?.status!==401){fail(e);return}} loginForm.userId='';loginForm.password='';clearFamily();sessionStorage.removeItem('tijianUser');sessionStorage.removeItem('tijianSelection');user.value=null;Object.keys(selection).forEach(k=>delete selection[k]);go('/login')}
const imagePath=(p)=>p && !p.includes('/')?'/img/'+p:'/img/hospita1.png';function fallbackImage(e){e.target.src='/img/hospita1.png'}
async function loadHospitals(){loading.value=true;try{hospitals.value=await call('/hospital/listHospital',{state:1})}catch(e){fail(e)}finally{loading.value=false}}
function clearFamily(){familyForm.patientName='';familyForm.patientSex=1;familyForm.patientIdentityCard='';familyForm.patientBirthday=''}
function chooseSelf(){clearFamily();selection.patient={patientType:1,patientName:user.value.realName,patientSex:user.value.sex};delete selection.hospital;delete selection.meal;delete selection.date;saveSelection();go('/hospital')}
function chooseFamily(){if(!/^[0-9]{17}[0-9Xx]$/.test(familyForm.patientIdentityCard)){error.value='请输入有效格式的 18 位身份证号';return}selection.patient={patientType:2,...familyForm};delete selection.hospital;delete selection.meal;delete selection.date;saveSelection();showFamily.value=false;go('/hospital')}
function selectHospital(h){if(!selection.patient)selection.patient={patientType:1,patientName:user.value.realName,patientSex:user.value.sex};selection.hospital=h;delete selection.meal;delete selection.date;saveSelection();mealType.value=selection.patient.patientSex===0?0:1;go('/setmeal')}
async function loadMeals(){loading.value=true;try{meals.value=await call('/setmeal/listSetmealByType',{type:mealType.value})}catch(e){fail(e)}finally{loading.value=false}}
async function toggleMealDetails(m){if(expandedMeal.value===m.smId){expandedMeal.value=null;return}expandedMeal.value=m.smId;if(mealDetails[m.smId])return;detailLoading.value=true;try{mealDetails[m.smId]=await call('/setmeal/listCheckItems',{smId:m.smId})}catch(e){fail(e)}finally{detailLoading.value=false}}
function setType(t){mealType.value=t;expandedMeal.value=null;loadMeals()}function selectMeal(m){selection.meal=m;delete selection.date;saveSelection();go('/selectDate')}
async function loadCalendar(){if(!selection.hospital)return;loading.value=true;try{calendar.value=await call('/calendar/listAppointmentCalendar',{hpId:selection.hospital.hpId,year:calendarYear.value,month:calendarMonth.value});if(selection.date && !calendar.value.some(d=>d.date===selection.date && d.available)){delete selection.date;saveSelection()}}catch(e){fail(e)}finally{loading.value=false}}
function shiftMonth(n){const d=new Date(calendarYear.value,calendarMonth.value-1+n,1);calendarYear.value=d.getFullYear();calendarMonth.value=d.getMonth()+1;delete selection.date;saveSelection();loadCalendar()}function pickDate(d){selection.date=d;saveSelection()}
async function submitOrder(){if(!selection.hospital||!selection.meal||!selection.date){error.value='请先选择机构、套餐和日期';return}if(busy.value)return;busy.value=true;error.value='';let orderId=null;try{const created=await call('/orders/savePendingOrder',{userId:user.value.userId,hpId:selection.hospital.hpId,smId:selection.meal.smId,orderDate:selection.date,...(selection.patient || {patientType:1})});orderId=created.orderId;await call('/payments/payAppointment',{orderId});Object.keys(selection).forEach(k=>delete selection[k]);clearFamily();saveSelection();await router.push({name:'appointmentSuccess',query:{orderId}})}catch(e){if(orderId){Object.keys(selection).forEach(k=>delete selection[k]);clearFamily();saveSelection();orderState.value=1;await router.push('/appointmentList');error.value='订单已创建，支付状态未确认，请在我的预约中查看并继续支付。'}else fail(e)}finally{busy.value=false}}
function backFromList(){go(route.query.from==='personal'?'/personal':'/home')}
async function loadOrders(state){loading.value=true;try{const list=await call('/orders/listOrdersByUserId',{userId:user.value.userId,state});orders.value=await Promise.all(list.map(async o=>{const [h,m]=await Promise.all([call('/hospital/getHospitalById',{hpId:o.hpId}),call('/setmeal/getSetmealById',{smId:o.smId})]);return {...o,hospitalName:h?.name,mealName:m?.name}}))}catch(e){fail(e)}finally{loading.value=false}}
function changeOrderState(s){orderState.value=s;loadOrders(s)} async function cancelOrder(o){if(!window.confirm(o.paymentStatus==='PAID'?'确定取消预约并模拟退款吗？':'确定取消这条预约吗？'))return;try{const n=await call('/orders/removeOrders',{orderId:o.orderId,userId:user.value.userId});if(!n){error.value='该预约无法取消，请刷新后重试';return}await loadOrders(orderState.value);success('预约已取消')}catch(e){fail(e)}}
async function payOrder(o){if(!window.confirm('确认模拟支付 ¥ '+o.paymentAmount+'？此操作不会产生实际扣款。'))return;busy.value=true;try{await call('/payments/payAppointment',{orderId:o.orderId});await router.push({name:'appointmentSuccess',query:{orderId:o.orderId}})}catch(e){fail(e)}finally{busy.value=false}}
function formatReportDate(value){const text=String(value||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(text)?text.slice(0,4)+'年'+text.slice(5,7)+'月'+text.slice(8,10)+'日':'体检'}
function openReport(o){router.push({name:'report',query:{orderId:o.orderId,...(route.query.from==='personal'?{from:'personal'}:{})}})}async function loadReport(){reportTab.value='summary';reportOrder.value=null;reports.value=[];conclusions.value=[];if(!Number.isInteger(reportOrderId.value)||reportOrderId.value<=0){error.value='预约编号无效';return}loading.value=true;try{[reportOrder.value,reports.value,conclusions.value]=await Promise.all([call('/orders/getOrdersById',{orderId:reportOrderId.value}),call('/ciReport/listCiReport',{orderId:reportOrderId.value}),call('/overallResult/listOverallResultByOrderId',{orderId:reportOrderId.value})])}catch(e){fail(e)}finally{loading.value=false}}
watch(()=>route.fullPath,()=>{error.value='';if(!user.value&&!isAuth.value){go('/login');return}if(route.name==='hospital')loadHospitals();if(route.name==='setmeal'){if(!selection.hospital){go('/hospital');return}loadMeals()}if(route.name==='selectDate'){if(!selection.meal||!selection.hospital){go('/hospital');return}loadCalendar()}if(route.name==='confirmOrder'&&(!selection.meal||!selection.hospital||!selection.date)){go('/hospital');return}if(route.name==='appointmentList')loadOrders(orderState.value);if(route.name==='reportList')loadOrders(2);if(route.name==='report')loadReport()},{immediate:true})
</script>
<style>
